<script setup>
import { onUnmounted, ref, watch } from 'vue';
const props = defineProps({ tenantId: [Number, String], page: String, canManage: Boolean, api: Function });
const billing = ref(null), tickets = ref(null), plans = ref([]), loading = ref(false), error = ref(''), success = ref(''), busy = ref(false), detail = ref(null), confirmation = ref('');
const selectedPlan = ref('business'), devices = ref(100), branches = ref(1), requirements = ref(''), subject = ref(''), message = ref('');
const pages = ref({ quotes_page: 1, orders_page: 1, payments_page: 1 });
let epoch = 0;
const labels = { requested: 'Chờ tư vấn', quoted: 'Báo giá đã gửi', pending_payment: 'Chờ thanh toán', pending_review: 'Chờ đối soát', paid: 'Đã thanh toán', cancelled: 'Đã hủy', active: 'Đang hiệu lực', open: 'Đang tiếp nhận', answered: 'Đã phản hồi', closed: 'Đã đóng' };
const label = value => labels[value] || value;
const money = value => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value);
const date = value => value ? new Date(value).toLocaleString('vi-VN') : '—';
async function load() {
    const token = ++epoch, id = props.tenantId;
    loading.value = true;
    try {
        if (props.page === 'support') {
            const result = await props.api(`tenants/${id}/tickets?page=${pages.value.quotes_page}`); if (token === epoch) tickets.value = result;
        } else if (props.canManage) {
            const query = new URLSearchParams(pages.value);
            const [result, catalog] = await Promise.all([props.api(`tenants/${id}/billing?${query}`), props.api('catalog')]);
            if (token === epoch) { billing.value = result; plans.value = catalog.plans; }
        }
    } catch (e) { if (token === epoch) error.value = e.message; }
    finally { if (token === epoch) loading.value = false; }
}
watch(() => [props.tenantId, props.page], () => { epoch++; billing.value = null; tickets.value = null; detail.value = null; error.value = ''; success.value = ''; confirmation.value = ''; pages.value = { quotes_page: 1, orders_page: 1, payments_page: 1 }; const plan = location.hash.split('plan=')[1]; if (plan && ['business','multisite','enterprise'].includes(plan)) selectedPlan.value = plan; load(); }, { immediate: true });
async function quote() {
    busy.value = true; error.value = ''; success.value = '';
    try { await props.api(`tenants/${props.tenantId}/quotes`, { method: 'POST', body: JSON.stringify({ plan_code: selectedPlan.value, devices: Number(devices.value), branches: Number(branches.value), requirements: requirements.value, idempotency_key: crypto.randomUUID() }) }); requirements.value = ''; success.value = 'Đã ghi nhận yêu cầu. TN20 sẽ khảo sát và gửi báo giá riêng trong mục Đơn hàng.'; await load(); }
    catch(e) { error.value = e.message; } finally { busy.value = false; }
}
async function action(value) {
    busy.value = true; error.value = '';
    try { const result = await props.api(`tenants/${props.tenantId}/orders/${detail.value.id}`, { method: 'POST', body: JSON.stringify({ action: value }) }); detail.value = result; confirmation.value = ''; success.value = value === 'report_transfer' ? 'Đã báo chuyển khoản. Đơn đang chờ TN20 đối soát, chưa kích hoạt dịch vụ.' : 'Đã cập nhật đơn hàng.'; await load(); }
    catch(e) { error.value = e.message; } finally { busy.value = false; }
}
async function sendTicket() {
    busy.value = true; error.value = '';
    try { await props.api(`tenants/${props.tenantId}/tickets`, { method: 'POST', body: JSON.stringify({ subject: subject.value, message: message.value }) }); subject.value = ''; message.value = ''; success.value = 'Đã lưu yêu cầu hỗ trợ. Bạn có thể theo dõi phản hồi tại đây.'; await load(); }
    catch(e) { error.value = e.message; } finally { busy.value = false; }
}
async function paginate(key, value) { pages.value[key] = value; await load(); }
onUnmounted(() => { epoch++; });
</script>
<template>
    <div class="commerce-panel">
        <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success-notice" role="status">{{ success }}</p>
        <p v-if="!canManage && page !== 'support'" class="notice">Chỉ chủ công ty và quản trị viên được xem báo giá, đơn hàng và thông tin thanh toán.</p>
        <template v-if="canManage && billing">
            <section v-if="page === 'quotes'" class="panel"><div class="section-heading"><h2>Tư vấn phương án NAC20</h2><span class="badge">Liên hệ báo giá</span></div><p class="muted">Mô tả nhu cầu để TN20 chuẩn bị báo giá. Gửi yêu cầu chưa tạo nghĩa vụ thanh toán hoặc cấp máy chủ.</p><form class="commerce-form" @submit.prevent="quote"><label>Gói định hướng<select v-model="selectedPlan"><option v-for="plan in plans" :key="plan.code" :value="plan.code">{{ plan.name }}</option></select></label><div class="form-columns"><label>Số thiết bị dự kiến<input v-model="devices" type="number" min="1" max="1000000" required></label><label>Số chi nhánh<input v-model="branches" type="number" min="1" max="10000" required></label></div><label>Nhu cầu và hiện trạng mạng<textarea v-model="requirements" maxlength="4000" rows="4" placeholder="Model switch/Wi-Fi, xác thực MAC hay 802.1X, yêu cầu hỗ trợ…"></textarea></label><button class="primary" :disabled="busy">{{ busy ? 'Đang gửi…' : 'Gửi yêu cầu báo giá →' }}</button></form></section>
            <section v-if="page === 'quotes'" class="panel"><h2>Yêu cầu đã gửi</h2><div class="table-scroll"><table v-if="billing.quotes.data.length"><thead><tr><th>Mã</th><th>Gói</th><th>Thiết bị / Chi nhánh</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="item in billing.quotes.data" :key="item.id"><td>#{{ item.id }}</td><td>{{ plans.find(p=>p.code===item.plan_code)?.name }}</td><td>{{ item.devices }} / {{ item.branches }}</td><td>{{ label(item.status) }}</td></tr></tbody></table><p v-else class="empty">Chưa có yêu cầu báo giá.</p></div><div class="pagination"><button :disabled="billing.quotes.current_page===1" @click="paginate('quotes_page',billing.quotes.current_page-1)">←</button><span>Trang {{ billing.quotes.current_page }} / {{ billing.quotes.last_page }}</span><button :disabled="billing.quotes.current_page>=billing.quotes.last_page" @click="paginate('quotes_page',billing.quotes.current_page+1)">→</button></div></section>
            <section v-if="page === 'orders'" class="panel"><div class="section-heading"><h2>Báo giá và đơn hàng</h2><button class="secondary" @click="load">↻ Cập nhật</button></div><div class="table-scroll"><table v-if="billing.orders.data.length"><thead><tr><th>Đơn hàng</th><th>Dịch vụ</th><th>Tổng thanh toán</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="order in billing.orders.data" :key="order.id"><td>{{ order.number }}</td><td>{{ order.plan_name }}</td><td>{{ money(order.amount_vnd) }}</td><td><span class="badge">{{ label(order.status) }}</span></td><td><button class="secondary" @click="detail=order; confirmation=''">Chi tiết</button></td></tr></tbody></table><p v-else class="empty">Chưa có báo giá. TN20 sẽ phát hành báo giá sau khi tiếp nhận nhu cầu của bạn.</p></div><div class="pagination"><button :disabled="billing.orders.current_page===1" @click="paginate('orders_page',billing.orders.current_page-1)">←</button><span>Trang {{ billing.orders.current_page }} / {{ billing.orders.last_page }}</span><button :disabled="billing.orders.current_page>=billing.orders.last_page" @click="paginate('orders_page',billing.orders.current_page+1)">→</button></div></section>
            <section v-if="page === 'orders' && detail" class="panel order-detail"><div class="section-heading"><h2>{{ detail.number }}</h2><button class="text-button" @click="detail=null">Đóng chi tiết ×</button></div><dl class="environment-facts"><div><dt>Dịch vụ</dt><dd>{{ detail.plan_name }}</dd></div><div><dt>Tổng thanh toán theo báo giá</dt><dd>{{ money(detail.amount_vnd) }}</dd></div><div><dt>Thời hạn dịch vụ</dt><dd>{{ detail.service_days }} ngày</dd></div><div><dt>Hạn xác nhận báo giá</dt><dd>{{ date(detail.expires_at) }}</dd></div></dl><h3>Phạm vi và điều khoản báo giá</h3><p class="preserve-text">{{ detail.terms }}</p><template v-if="['pending_payment','pending_review'].includes(detail.status)"><div v-if="billing.bank" class="bank-box"><h3>Hướng dẫn chuyển khoản</h3><p>{{ billing.bank.name }} · <b>{{ billing.bank.account_number }}</b></p><p>Chủ tài khoản: {{ billing.bank.account_holder }}</p><p>Số tiền: <b>{{ money(detail.amount_vnd) }}</b></p><p>Nội dung: <b>{{ detail.number }}</b></p></div><p v-else class="notice">TN20 chưa công bố thông tin chuyển khoản trên hệ thống. Vui lòng trao đổi qua mục Hỗ trợ trước khi thanh toán.</p><p v-if="detail.status==='pending_review'" class="notice">Đang chờ TN20 đối soát. Thông báo chuyển khoản không đồng nghĩa đã nhận tiền.</p></template><div class="cta-row"><button v-if="detail.status==='quoted' && new Date(detail.expires_at)>new Date()" class="primary" @click="confirmation='accept'">Xác nhận báo giá</button><button v-if="detail.status==='pending_payment' && billing.bank" class="primary" @click="confirmation='report_transfer'">Tôi đã chuyển khoản</button><button v-if="['quoted','pending_payment'].includes(detail.status)" class="secondary" @click="confirmation='cancel'">Hủy đơn</button></div><div v-if="confirmation" class="confirmation-box"><p>{{ confirmation==='accept' ? 'Bạn xác nhận đồng ý giá, thời hạn và các điều khoản báo giá hiển thị phía trên?' : confirmation==='cancel' ? 'Bạn muốn hủy đơn này? Nếu đã chuyển tiền, hãy liên hệ TN20 để đối soát.' : 'Bạn đã thực hiện chuyển khoản đúng thông tin? TN20 vẫn cần đối soát trước khi kích hoạt.' }}</p><button class="primary" :disabled="busy" @click="action(confirmation)">Xác nhận</button><button class="text-button" @click="confirmation=''">Quay lại</button></div><p v-if="detail.status==='paid'" class="success-notice">Thanh toán đã được TN20 xác nhận lúc {{ date(detail.paid_at) }}. Theo dõi triển khai tại mục Hạ tầng NAC20.</p><p class="fine">Đây là thông tin đơn dịch vụ, không thay thế hóa đơn thuế.</p></section>
            <section v-if="page === 'payments'" class="panel"><div class="section-heading"><h2>Lịch sử giao dịch đã đối soát</h2><button class="secondary" @click="load">↻ Cập nhật</button></div><div class="table-scroll"><table v-if="billing.payments.data.length"><thead><tr><th>Đơn ID</th><th>Số tiền</th><th>Tham chiếu</th><th>Ngày xác nhận</th></tr></thead><tbody><tr v-for="payment in billing.payments.data" :key="payment.id"><td>#{{ payment.order_id }}</td><td>{{ money(payment.amount_vnd) }}</td><td>{{ payment.reference }}</td><td>{{ date(payment.verified_at) }}</td></tr></tbody></table><p v-else class="empty">Chưa có giao dịch được xác nhận.</p></div><div class="pagination"><button :disabled="billing.payments.current_page===1" @click="paginate('payments_page',billing.payments.current_page-1)">←</button><span>Trang {{ billing.payments.current_page }} / {{ billing.payments.last_page }}</span><button :disabled="billing.payments.current_page>=billing.payments.last_page" @click="paginate('payments_page',billing.payments.current_page+1)">→</button></div></section>
            <section v-if="page === 'subscription'" class="panel"><h2>Dịch vụ và thời hạn</h2><template v-if="billing.subscription"><dl class="environment-facts"><div><dt>Gói hiện tại</dt><dd>{{ plans.find(p=>p.code===billing.subscription.plan_code)?.name || 'Theo thỏa thuận TN20' }}</dd></div><div><dt>Hiệu lực đến</dt><dd>{{ date(billing.subscription.expires_at) }}</dd></div><div><dt>Trạng thái</dt><dd>{{ new Date(billing.subscription.expires_at)>new Date() ? label(billing.subscription.status) : 'Đã hết thời hạn' }}</dd></div></dl><p class="muted">Gia hạn được xử lý theo báo giá riêng và chỉ cộng thời hạn sau khi đối soát. Thay gói cần thống nhất tác động hạ tầng với TN20.</p></template><p v-else class="empty">Chưa có thuê bao được kích hoạt. Bắt đầu bằng yêu cầu báo giá.</p></section>
        </template>
        <template v-if="page === 'support'"><section class="panel"><h2>Gửi yêu cầu hỗ trợ</h2><p class="muted">Trao đổi triển khai, báo giá hoặc sự cố. Không gửi mật khẩu, token hoặc khóa RADIUS.</p><form class="commerce-form" @submit.prevent="sendTicket"><label>Tiêu đề<input v-model="subject" maxlength="180" required></label><label>Nội dung<textarea v-model="message" rows="4" minlength="10" maxlength="6000" required></textarea></label><button class="primary" :disabled="busy">Gửi yêu cầu</button></form></section><section v-if="tickets" class="panel"><div class="section-heading"><h2>Yêu cầu của công ty</h2><button class="secondary" @click="load">↻ Cập nhật</button></div><article v-for="ticket in tickets.data" :key="ticket.id" class="ticket-item"><div class="section-heading"><h3>#{{ ticket.id }} · {{ ticket.subject }}</h3><span class="badge">{{ label(ticket.status) }}</span></div><p class="preserve-text">{{ ticket.message }}</p><div v-if="ticket.reply" class="notice"><b>TN20 phản hồi</b><p class="preserve-text">{{ ticket.reply }}</p></div></article><p v-if="!tickets.data.length" class="empty">Chưa có yêu cầu hỗ trợ.</p><div class="pagination"><button :disabled="tickets.current_page===1" @click="paginate('quotes_page',tickets.current_page-1)">←</button><span>Trang {{ tickets.current_page }} / {{ tickets.last_page }}</span><button :disabled="tickets.current_page>=tickets.last_page" @click="paginate('quotes_page',tickets.current_page+1)">→</button></div></section></template>
        <p v-if="loading && !billing && !tickets" role="status" class="empty">Đang tải dữ liệu…</p>
    </div>
</template>
